  ?z a brick:Zone ; rdfs:label "Perimeter_top_ZN_3" .
  ?point brick:hasLocation ?z ; a brick:OccupancySensor .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point rdfs:label ?label }
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_top_ZN"))
}

SELECT ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
} LIMIT 50

SELECT ?cls ?n WHERE {
  ?s a ?cls .
  FILTER(?cls != rdf:Property)
  GROUP BY ?cls
} LIMIT 100

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_top_ZN_3"))
}

SELECT ?point ?label WHERE {
  ?point a brick:OccupancySensor .
  OPTIONAL {?point rdfs:label ?label}
} LIMIT 50

SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER(LCASE(?label) = ?label && (CONTAINS(LCASE(?label), "occup") || CONTAINS(LCASE(?label), "top")))
} LIMIT 50

